58	type PositionalEncoding struct {
59		graph    *gorgonia.ExprGraph
60		encoding *gorgonia.Node
61		seqLen   int
62		embedDim int
63	}
64	
65	func NewPositionalEncoding(g *gorgonia.ExprGraph, seqLen, embedDim int) *PositionalEncoding {
66		encoding := make([]float32, seqLen*embedDim)
67	
68		for pos := 0; pos < seqLen; pos++ {
69			for i := 0; i < embedDim; i++ {
70				angle := float64(pos) / math.Pow(10000, float64(2*i)/float64(embedDim))
71				if i%2 == 0 {
72					encoding[pos*embedDim+i] = float32(math.Sin(angle))
73				} else {
74					encoding[pos*embedDim+i] = float32(math.Cos(angle))
75				}
76			}
77		}
78	
79		posEncTensor := tensor.New(
80			tensor.WithBacking(encoding),
81			tensor.WithShape(seqLen, embedDim),
82		)
83	
84		posEncNode := gorgonia.NewConstant(posEncTensor, gorgonia.WithName("pos_encoding"))
85	
86		return &PositionalEncoding{
87			graph:    g,
88			encoding: posEncNode,
89			seqLen:   seqLen,
90			embedDim: embedDim,
91		}
92	}
