108	func NewSelfAttention(g *gorgonia.ExprGraph, embedDim, headDim int, dropout float64, seqLen int) *SelfAttention {
109		wq := gorgonia.NewMatrix(g, tensor.Float32,
110			gorgonia.WithShape(embedDim, headDim),
111			gorgonia.WithName("w_query"),
112			gorgonia.WithInit(gorgonia.GlorotN(1.0)),
113		)
114	
115		wk := gorgonia.NewMatrix(g, tensor.Float32,
116			gorgonia.WithShape(embedDim, headDim),
117			gorgonia.WithName("w_key"),
118			gorgonia.WithInit(gorgonia.GlorotN(1.0)),
119		)
120	
121		wv := gorgonia.NewMatrix(g, tensor.Float32,
122			gorgonia.WithShape(embedDim, headDim),
123			gorgonia.WithName("w_value"),
124			gorgonia.WithInit(gorgonia.GlorotN(1.0)),
125		)
126	
127		return &SelfAttention{
128			graph:    g,
129			wQuery:   wq,
130			wKey:     wk,
131			wValue:   wv,
132			embedDim: embedDim,
133			headDim:  headDim,
134			dropout:  dropout,
135		}
136	}
