138	func (sa *SelfAttention) Forward(x *gorgonia.Node, mask *gorgonia.Node, training bool) (*gorgonia.Node, error) {
139		q, err := gorgonia.Mul(x, sa.wQuery)
140		if err != nil {
141			return nil, err
142		}
143	
144		k, err := gorgonia.Mul(x, sa.wKey)
145		if err != nil {
146			return nil, err
147		}
148	
149		v, err := gorgonia.Mul(x, sa.wValue)
150		if err != nil {
151			return nil, err
152		}
153	
154		kT, err := gorgonia.Transpose(k)
155		if err != nil {
156			return nil, err
157		}
158	
159		scores, err := gorgonia.Mul(q, kT)
160		if err != nil {
161			return nil, err
162		}
163	
164		// Debug logging for node IDs
165		fmt.Printf("Debug: q ID: %d, k ID: %d, kT ID: %d, scores ID: %d\n", q.ID(), k.ID(), kT.ID(), scores.ID())
166	
167		scale := float32(1.0 / math.Sqrt(float64(sa.headDim)))
168		scaleNode := gorgonia.NewScalar(sa.graph, tensor.Float32, gorgonia.WithValue(scale))
169		scores, err = gorgonia.HadamardProd(scores, scaleNode)
170		if err != nil {
171			return nil, err
172		}
173	
174		// if mask != nil {
175		// 	scores, err = gorgonia.Add(scores, mask)
176		// 	if err != nil {
177		// 		return nil, err
178		// 	}
179		// }
180	
181		// attnWeights, err := gorgonia.SoftMax(scores)
182		// if err != nil {
183		// 	return nil, err
184		// }
185		attnWeights := scores
186	
187		// if training && sa.dropout > 0 {
188		// 	attnWeights, err = gorgonia.Dropout(attnWeights, sa.dropout)
189		// 	if err != nil {
190		// 		return nil, err
191		// 	}
192		// }
193	
194		output, err := gorgonia.Mul(attnWeights, v)
195		if err != nil {
196			return nil, err
197		}
198	
199		return output, nil
200	}
