202	type MultiHeadAttention struct {
203		graph       *gorgonia.ExprGraph
204		heads       []*SelfAttention
205		wOutput     *gorgonia.Node
206		numHeads    int
207		embedDim    int
208		headDim     int
209	}
210	
211	func NewMultiHeadAttention(g *gorgonia.ExprGraph, embedDim, numHeads int, dropout float64, seqLen int) *MultiHeadAttention {
212		headDim := embedDim / numHeads
213	
214		heads := make([]*SelfAttention, numHeads)
215		for i := 0; i < numHeads; i++ {
216			heads[i] = NewSelfAttention(g, embedDim, headDim, dropout, seqLen)
217		}
218	
219		wOut := gorgonia.NewMatrix(g, tensor.Float32,
220			gorgonia.WithShape(headDim, embedDim),
221			gorgonia.WithName("w_output"),
222			gorgonia.WithInit(gorgonia.GlorotN(1.0)),
223		)
224	
225		return &MultiHeadAttention{
226			graph:    g,
227			heads:    heads,
228			wOutput:  wOut,
229			numHeads: numHeads,
230			embedDim: embedDim,
231			headDim:  headDim,
232		}
233	}
234	
235	func (mha *MultiHeadAttention) Forward(x *gorgonia.Node, mask *gorgonia.Node, training bool) (*gorgonia.Node, error) {
236		headOutputs := make([]*gorgonia.Node, mha.numHeads)
237		for i := 0; i < mha.numHeads; i++ {
238			out, err := mha.heads[i].Forward(x, mask, training)
239			if err != nil {
240				return nil, err
241			}
242			headOutputs[i] = out
243		}
244	
245		// Sum the head outputs instead of concatenating
246		result := headOutputs[0]
247		for i := 1; i < len(headOutputs); i++ {
248			var err error
249			result, err = gorgonia.Add(result, headOutputs[i])
250			if err != nil {
251				return nil, err
252			}
253		}
254	
255		output, err := gorgonia.Mul(result, mha.wOutput)
256		if err != nil {
257			return nil, err
258		}
259	
260		return output, nil
261	}
