263	type FeedForward struct {
264		graph      *gorgonia.ExprGraph
265		w1         *gorgonia.Node
266		w2         *gorgonia.Node
267		dropout    float64
268	}
269	
270	func NewFeedForward(g *gorgonia.ExprGraph, embedDim int, dropout float64) *FeedForward {
271		hiddenDim := embedDim * 4
272	
273		w1 := gorgonia.NewMatrix(g, tensor.Float32,
274			gorgonia.WithShape(embedDim, hiddenDim),
275			gorgonia.WithName("ffn_w1"),
276			gorgonia.WithInit(gorgonia.GlorotN(1.0)),
277		)
278	
279		w2 := gorgonia.NewMatrix(g, tensor.Float32,
280			gorgonia.WithShape(hiddenDim, embedDim),
281			gorgonia.WithName("ffn_w2"),
282			gorgonia.WithInit(gorgonia.GlorotN(1.0)),
283		)
284	
285		return &FeedForward{
286			graph:   g,
287			w1:      w1,
288			w2:      w2,
289			dropout: dropout,
290		}
291	}
292	
293	func (ff *FeedForward) Forward(x *gorgonia.Node, training bool) (*gorgonia.Node, error) {
294		hidden, err := gorgonia.Mul(x, ff.w1)
295		if err != nil {
296			return nil, err
297		}
298	
299		// Simplified activation (should be GELU)
300		hidden, err = gorgonia.Tanh(hidden)
301		if err != nil {
302			return nil, err
303		}
304	
305		// if training && ff.dropout > 0 {
306		// 	hidden, err = gorgonia.Dropout(hidden, ff.dropout)
307		// 	if err != nil {
308		// 		return nil, err
309		// 	}
310		// }
311	
312		output, err := gorgonia.Mul(hidden, ff.w2)
313		if err != nil {
314			return nil, err
315		}
316	
317		return output, nil
318	}
