320	type TransformerBlock struct {
321		graph       *gorgonia.ExprGraph
322		attention   *MultiHeadAttention
323		feedForward *FeedForward
324	}
325	
326	func NewTransformerBlock(g *gorgonia.ExprGraph, embedDim, numHeads int, dropout float64, seqLen int) *TransformerBlock {
327		return &TransformerBlock{
328			graph:       g,
329			attention:   NewMultiHeadAttention(g, embedDim, numHeads, dropout, seqLen),
330			feedForward: NewFeedForward(g, embedDim, dropout),
331		}
332	}
333	
334	func (tb *TransformerBlock) Forward(x *gorgonia.Node, mask *gorgonia.Node, training bool) (*gorgonia.Node, error) {
335		attnOut, err := tb.attention.Forward(x, mask, training)
336		if err != nil {
337			return nil, err
338		}
339	
340		x, err = gorgonia.Add(x, attnOut)
341		if err != nil {
342			return nil, err
343		}
344	
345		ffOut, err := tb.feedForward.Forward(x, training)
346		if err != nil {
347			return nil, err
348		}
349	
350		x, err = gorgonia.Add(x, ffOut)
351		if err != nil {
352			return nil, err
353		}
354	
355		return x, nil
356	}
