358	type GPT struct {
359		graph          *gorgonia.ExprGraph
360		config         TransformerConfig
361		embedding      *EmbeddingLayer
362		posEncoding    *PositionalEncoding
363		blocks         []*TransformerBlock
364		outputLayer    *gorgonia.Node
365		logits         *gorgonia.Node
366		loss           *gorgonia.Node
367		learnables     []*gorgonia.Node
368	}
369	
370	func NewGPT(config TransformerConfig) *GPT {
371		g := gorgonia.NewGraph()
372	
373		embedding := NewEmbeddingLayer(g, config.VocabSize, config.EmbedDim, config.ContextLen)
374		posEncoding := NewPositionalEncoding(g, config.ContextLen, config.EmbedDim)
375	
376		blocks := make([]*TransformerBlock, config.NumLayers)
377		for i := 0; i < config.NumLayers; i++ {
378			blocks[i] = NewTransformerBlock(g, config.EmbedDim, config.NumHeads, config.DropoutRate, config.ContextLen)
379		}
380	
381		outputLayer := gorgonia.NewMatrix(g, tensor.Float32,
382			gorgonia.WithShape(config.EmbedDim, config.VocabSize),
383			gorgonia.WithName("output_projection"),
384			gorgonia.WithInit(gorgonia.GlorotN(1.0)),
385		)
386	
387		// Collect learnable nodes (weights)
388		learnables := []*gorgonia.Node{embedding.embeddings, outputLayer}
389		// Attention and FFN weights from blocks
390		for _, block := range blocks {
391			learnables = append(learnables, block.attention.wOutput)
392			for _, head := range block.attention.heads {
393				learnables = append(learnables, head.wQuery, head.wKey, head.wValue)
394			}
395			learnables = append(learnables, block.feedForward.w1, block.feedForward.w2)
396		}
397	
398		gpt := &GPT{
399			graph:       g,
400			config:      config,
401			embedding:   embedding,
402			posEncoding: posEncoding,
403			blocks:      blocks,
404			outputLayer: outputLayer,
405			learnables:  learnables,
406		}
407	
408		// Build the graph
409		seqLen := config.ContextLen
410		x, err := embedding.Forward(seqLen)
411		if err != nil {
412			panic(err)
413		}
414	
415		// posEnc, err := posEncoding.Forward(seqLen)
416		// if err != nil {
417		// 	panic(err)
418		// }
419	
420		// x, err = gorgonia.Add(x, posEnc)
421		// if err != nil {
422		// 	panic(err)
423		// }
424	
425		mask := createCausalMask(g, seqLen)
426	
427		for _, block := range blocks {
428			x, err = block.Forward(x, mask, false)
429			if err != nil {
430				panic(err)
431			}
432		}
433	
434		logits, err := gorgonia.Mul(x, outputLayer)
435		if err != nil {
436			panic(err)
437		}
438	
439		gpt.logits = logits
440	
441		loss, err := gorgonia.Mean(logits)
442		if err != nil {
443			panic(err)
444		}
445		gpt.loss = loss
446	
447		fmt.Printf("Graph has %d nodes\n", len(g.AllNodes()))
448	
449		return gpt
450	}
451	
452	func (gpt *GPT) Forward(training bool) (*gorgonia.Node, error) {
453		return gpt.logits, nil
454	}
