456	func createCausalMask(_ *gorgonia.ExprGraph, seqLen int) *gorgonia.Node {
457		maskData := make([]float32, seqLen*seqLen)
458		for i := 0; i < seqLen; i++ {
459			for j := i + 1; j < seqLen; j++ {
460				maskData[i*seqLen+j] = -1e10
461			}
462		}
463	
464		maskTensor := tensor.New(
465			tensor.WithBacking(maskData),
466			tensor.WithShape(seqLen, seqLen),
467		)
468	
469		return gorgonia.NewConstant(maskTensor)
470	}
