472	type Dataset struct {
473		inputs  [][]int
474		targets [][]int
475	}
476	
477	func PrepareDataset(text string, tokenizer Tokenizer, contextLen, stride int) *Dataset {
478		tokens := tokenizer.Encode(text)
479	
480		dataset := &Dataset{
481			inputs:  make([][]int, 0),
482			targets: make([][]int, 0),
483		}
484	
485		for i := 0; i+contextLen < len(tokens); i += stride {
486			input := tokens[i : i+contextLen]
487			target := tokens[i+1 : i+contextLen+1]
488			dataset.inputs = append(dataset.inputs, input)
489			dataset.targets = append(dataset.targets, target)
490		}
491	
492		return dataset
493	}
