523	func TrainModel(model *GPT, dataset *Dataset, config TrainConfig) error {
524		vm := gorgonia.NewTapeMachine(model.graph, gorgonia.BindDualValues())
525		defer vm.Close()
526	
527		solver := gorgonia.NewVanillaSolver(gorgonia.WithLearnRate(config.LearningRate))
528	
529		for epoch := 0; epoch < config.NumEpochs; epoch++ {
530			epochLoss := 0.0
531	
532			for i := 0; i < len(dataset.inputs); i += config.BatchSize {
533				_, err := model.Forward(true)
534				if err != nil {
535					return fmt.Errorf("forward pass error: %w", err)
536				}
537	
538				loss := model.loss
539	
540				if err := vm.RunAll(); err != nil {
541					return fmt.Errorf("VM execution error: %w", err)
542				}
543	
544				fmt.Printf("Debug: Loss node ID: %d, Shape: %v\n", loss.ID(), loss.Shape())
545				fmt.Printf("Debug: Computing gradients for %d learnables\n", len(model.learnables))
546	
547				grads, err := gorgonia.Grad(loss, model.learnables...)
548				if err != nil {
549					fmt.Printf("Debug: gorgonia.Grad failed: %v\n", err)
550					return fmt.Errorf("backward pass error: %w", err)
551				}
552	
553				fmt.Printf("Debug: Gradients computed successfully for %d nodes\n", len(grads))
554				for i, g := range grads {
555					if g != nil {
556						fmt.Printf("Debug: Grad %d ID: %d, Shape: %v\n", i, g.ID(), g.Shape())
557					} else {
558						fmt.Printf("Debug: Grad %d is nil\n", i)
559					}
560				}
561	
562				// Run backward pass to compute gradient values
563				if err := vm.RunAll(); err != nil {
564					fmt.Printf("Debug: Backward VM run failed: %v\n", err)
565					return fmt.Errorf("backward VM run error: %w", err)
566				}
567	
568				valueGrads := gorgonia.NodesToValueGrads(grads)
569				fmt.Printf("Debug: Converted to %d ValueGrads\n", len(valueGrads))
570				for i, vg := range valueGrads {
571					gradVal, err := vg.Grad()
572					if err != nil {
573						fmt.Printf("Debug: ValueGrad %d grad error: %v\n", i, err)
574					} else if gradVal != nil {
575						fmt.Printf("Debug: ValueGrad %d has grad value, shape: %v\n", i, gradVal.Shape())
576					} else {
577						fmt.Printf("Debug: ValueGrad %d has nil grad value\n", i)
578					}
579				}
580	
581				if err := solver.Step(valueGrads); err != nil {
582					fmt.Printf("Debug: Solver step failed: %v\n", err)
583					// Print more details about the graph
584					fmt.Printf("Debug: Graph nodes: %d\n", len(model.graph.AllNodes()))
585					for _, node := range model.graph.AllNodes() {
586						if node.Value() != nil {
587							fmt.Printf("Debug: Node %d (%s): shape %v, has value\n", node.ID(), node.Name(), node.Shape())
588						} else {
589							fmt.Printf("Debug: Node %d (%s): shape %v, no value\n", node.ID(), node.Name(), node.Shape())
590						}
591					}
592					return fmt.Errorf("solver step error: %w", err)
593				}
594	
595				vm.Reset()
596	
597				lossValue := loss.Value().Data().(float32)
598				epochLoss += float64(lossValue)
599			}
600	
601			avgLoss := epochLoss / float64(len(dataset.inputs)/config.BatchSize)
602			fmt.Printf("Epoch %d: Loss = %.4f\n", epoch, avgLoss)
603	
604			if epoch%config.SaveFreq == 0 {
605				SaveModel(model, fmt.Sprintf("checkpoint_epoch_%d.bin", epoch))
606			}
607		}
608	
609		return nil
610	}
