613	func SaveModel(model *GPT, filepath string) error {
614		file, err := os.Create(filepath)
615		if err != nil {
616			return err
617		}
618		defer file.Close()
619	
620		encoder := gob.NewEncoder(file)
621	
622		params := make(map[string][]float32)
623	
624		for _, node := range model.graph.AllNodes() {
625			if node.Value() != nil {
626				data := node.Value().Data()
627				switch v := data.(type) {
628				case []float32:
629					params[node.Name()] = v
630				case []float64:
631					f32 := make([]float32, len(v))
632					for i, val := range v {
633						f32[i] = float32(val)
634					}
635					params[node.Name()] = f32
636				}
637			}
638		}
639	
640		return encoder.Encode(params)
641	}
642	
643	func LoadModel(model *GPT, filepath string) error {
644		file, err := os.Open(filepath)
645		if err != nil {
646			return err
647		}
648		defer file.Close()
649	
650		decoder := gob.NewDecoder(file)
651		params := make(map[string][]float32)
652	
653		if err := decoder.Decode(&params); err != nil {
654			return err
655		}
656	
657		for _, node := range model.graph.AllNodes() {
658			if data, exists := params[node.Name()]; exists {
659				t := tensor.New(
660					tensor.WithBacking(data),
661					tensor.WithShape(node.Shape()...),
662				)
663				gorgonia.Let(node, t)
664			}
665		}
666	
667		return nil
668	}
