670	func Generate(model *GPT, startTokens []int, maxNewTokens int, temperature float32, topK int) []int {
671		tokens := make([]int, len(startTokens))
672		copy(tokens, startTokens)
673	
674		vm := gorgonia.NewTapeMachine(model.graph)
675		defer vm.Close()
676	
677		for i := 0; i < maxNewTokens; i++ {
678			context := tokens
679			if len(context) > model.config.ContextLen {
680				context = context[len(context)-model.config.ContextLen:]
681			}
682	
683			logits, err := model.Forward(false)
684			if err != nil {
685				log.Fatal(err)
686			}
687	
688			if err := vm.RunAll(); err != nil {
689				log.Fatal(err)
690			}
691	
692			logitsData := logits.Value().Data().([]float32)
693			lastLogits := logitsData[len(context)*model.config.VocabSize:]
694	
695			nextToken := SampleToken(lastLogits[:model.config.VocabSize], temperature, topK)
696			tokens = append(tokens, nextToken)
697	
698			vm.Reset()
699		}
700	
701		return tokens
702	}
