704	func SampleToken(logits []float32, temperature float32, topK int) int {
705		if temperature != 1.0 {
706			for i := range logits {
707				logits[i] /= temperature
708			}
709		}
710	
711		maxLogit := logits[0]
712		for _, l := range logits {
713			if l > maxLogit {
714				maxLogit = l
715			}
716		}
717	
718		expSum := float32(0)
719		probs := make([]float32, len(logits))
720		for i, l := range logits {
721			probs[i] = float32(math.Exp(float64(l - maxLogit)))
722			expSum += probs[i]
723		}
724	
725		for i := range probs {
726			probs[i] /= expSum
727		}
728	
729		if topK > 0 && topK < len(probs) {
730			type indexedProb struct {
731				idx  int
732				prob float32
733			}
734	
735			indexed := make([]indexedProb, len(probs))
736			for i, p := range probs {
737				indexed[i] = indexedProb{i, p}
738			}
739	
740			sort.Slice(indexed, func(i, j int) bool {
741				return indexed[i].prob > indexed[j].prob
742			})
743	
744			for i := topK; i < len(indexed); i++ {
745				probs[indexed[i].idx] = 0
746			}
747	
748			sum := float32(0)
749			for _, p := range probs {
750				sum += p
751			}
752			for i := range probs {
753				probs[i] /= sum
754			}
755		}
756	
757		r := rand.Float32()
758		cumulative := float32(0)
759		for i, p := range probs {
760			cumulative += p
761			if r < cumulative {
762				return i
763			}
764		}
765	
766		return len(probs) - 1
767	}
