257	// ProcessRawMetrics converts raw network metrics to HEART input format
258	func (nmp *NetworkMetricsProcessor) ProcessRawMetrics(metrics map[uint32]map[uint32][]float32) *HEARTInput {
259		// metrics: map[nodeID]map[timeSlice]metricVector
260		input := &HEARTInput{
261			Measurements: make([][]float32, 0, nmp.sequenceLength*nmp.numNodes),
262			NodeIDs:      make([]uint32, 0, nmp.sequenceLength*nmp.numNodes),
263			TimeSlices:   make([]uint32, 0, nmp.sequenceLength*nmp.numNodes),
264		}
265	
266		// Flatten the metrics into sequence format
267		for t := uint32(0); t < uint32(nmp.sequenceLength); t++ {
268			for n := uint32(0); n < uint32(nmp.numNodes); n++ {
269				var metricVec []float32
270				if nodeMetrics, ok := metrics[n]; ok {
271					if vec, ok := nodeMetrics[t]; ok {
272						metricVec = vec
273					}
274				}
275	
276				// Ensure vector is correct size (pad or truncate)
277				if len(metricVec) < nmp.measureVecSize {
278					padded := make([]float32, nmp.measureVecSize)
279					copy(padded, metricVec)
280					metricVec = padded
281				} else if len(metricVec) > nmp.measureVecSize {
282					metricVec = metricVec[:nmp.measureVecSize]
283				}
284	
285				// Apply adaptive Z-score normalization
286				normalized := nmp.normalizeMetrics(metricVec, n, t)
287	
288				input.Measurements = append(input.Measurements, normalized)
289				input.NodeIDs = append(input.NodeIDs, n)
290				input.TimeSlices = append(input.TimeSlices, t)
291			}
292		}
293	
294		return input
295	}
