297	// normalizeMetrics applies adaptive Z-score normalization
298	func (nmp *NetworkMetricsProcessor) normalizeMetrics(metrics []float32, nodeID, timeSlice uint32) []float32 {
299		normalized := make([]float32, len(metrics))
300	
301		// Calculate running mean and stddev
302		for i, val := range metrics {
303			key := fmt.Sprintf("metric_%d_node_%d", i, nodeID)
304	
305			stats, exists := nmp.normalizationStats[key]
306			if !exists {
307				stats = struct{ Mean, StdDev float32 }{Mean: val, StdDev: 1.0}
308			}
309	
310			// Exponential moving average
311			alpha := float32(0.1)
312			newMean := alpha*val + (1-alpha)*stats.Mean
313			newStdDev := alpha*float32(math.Abs(float64(val-stats.Mean))) + (1-alpha)*stats.StdDev
314	
315			nmp.normalizationStats[key] = struct{ Mean, StdDev float32 }{newMean, newStdDev}
316	
317			// Normalize
318			if newStdDev > 1e-6 {
319				normalized[i] = (val - newMean) / newStdDev
320			} else {
321				normalized[i] = 0.0
322			}
323		}
324	
325		return normalized
326	}
